    pub score: i64,
    pub attempt: u32,
    pub division: String,
}

pub fn select_finalists(entries: &[Entry], limit: usize) -> Vec<Entry> {
    let mut ranked = entries.to_vec();
    ranked.sort_by(|a, b| {
        b.score
            .cmp(&a.score)
            .then_with(|| a.attempt.cmp(&b.attempt))
            .then_with(|| a.entrant.cmp(&b.entrant))
            .then_with(|| a.division.cmp(&b.division))
    });

    let mut seen = HashSet::new();
