#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Allocation {
    pub name: String,
    pub units: u32,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ManifestError {
    EmptyInput,
    EmptyRecord { record: usize },
    SeparatorCount { record: usize },
    InvalidName { record: usize },
    InvalidUnits { record: usize },
}

pub fn parse_manifest(input: &str) -> Result<Vec<Allocation>, ManifestError>;
```

The format is one or more records separated by `;`. Record indices in errors are zero-based. Every record must contain exactly one `=` and have the form `name=units`.

A name must contain one or more lowercase ASCII letters (`a` through `z`). Units must be a canonical unsigned decimal representation: one or more ASCII digits, no leading zero when more than one digit is present, and a value representable by `u32`. Whitespace is never ignored. Preserve record order and allow repeated names as independent records.

Error precedence is left-to-right by record. For a record, report `EmptyRecord` first, then `SeparatorCount`, then `InvalidName`, then `InvalidUnits`. An empty overall string produces `EmptyInput`; a trailing semicolon therefore produces `EmptyRecord` for its final record.","reference_code":"#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Allocation {
    pub name: String,
    pub units: u32,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ManifestError {
    EmptyInput,
    EmptyRecord { record: usize },
    SeparatorCount { record: usize },
    InvalidName { record: usize },
    InvalidUnits { record: usize },
}

pub fn parse_manifest(input: &str) -> Result<Vec<Allocation>, ManifestError> {
    if input.is_empty() {
        return Err(ManifestError::EmptyInput);
    }

    let mut allocations = Vec::new();
    for (record, text) in input.split(';').enumerate() {
        if text.is_empty() {
            return Err(ManifestError::EmptyRecord { record });
        }
        if text.bytes().filter(|&byte| byte == b'=').count() != 1 {
            return Err(ManifestError::SeparatorCount { record });
        }

        let (name, units_text) = text.split_once('=').unwrap();
        if name.is_empty() || !name.bytes().all(|byte| byte.is_ascii_lowercase()) {
            return Err(ManifestError::InvalidName { record });
        }
        if units_text.is_empty()
            || !units_text.bytes().all(|byte| byte.is_ascii_digit())
            || (units_text.len() > 1 && units_text.starts_with('0'))
        {
            return Err(ManifestError::InvalidUnits { record });
        }
        let units = units_text
            .parse::<u32>()
            .map_err(|_| ManifestError::InvalidUnits { record })?;
        allocations.push(Allocation {
            name: name.to_owned(),
            units,
        });
    }

    Ok(allocations)
}
