        entry("b", 2, 3, "west"),
        entry("a", 4, 1, "east"),
        entry("a", 3, 0, "north"),
    ];
    let original = entries.clone();

    let _ = select_finalists(&entries, 2);

    assert_eq!(entries, original);
}
