mod solution;

use solution::select_label;

#[test]
fn selects_by_increasing_byte_length_then_lexicographically() {
    let mut labels = vec![
        "pear".to_string(),
        "a".to_string(),
        "fig".to_string(),
        "kiwi".to_string(),
        "be".to_string(),
        "apple".to_string(),
    ];

    assert_eq!(select_label(&mut labels, 0), Some("a"));
    assert_eq!(select_label(&mut labels, 1), Some("be"));
    assert_eq!(select_label(&mut labels, 2), Some("fig"));
    assert_eq!(select_label(&mut labels, 3), Some("kiwi"));
    assert_eq!(select_label(&mut labels, 4), Some("pear"));
    assert_eq!(select_label(&mut labels, 5), Some("apple"));
}

#[test]
fn uses_utf8_byte_length_rather_than_character_count() {
    let mut labels = vec![
        "é".to_string(),
        "z".to_string(),
        "abc".to_string(),
        "界".to_string(),
    ];

    assert_eq!(select_label(&mut labels, 0), Some("z"));
    assert_eq!(select_label(&mut labels, 1), Some("é"));
    assert_eq!(select_label(&mut labels, 2), Some("abc"));
    assert_eq!(select_label(&mut labels, 3), Some("界"));
}

#[test]
fn identical_labels_tie_by_original_index() {
    let first = String::from("same");
    let second = String::from("same");
    let third = String::from("same");
    let first_ptr = first.as_ptr();
    let second_ptr = second.as_ptr();
    let third_ptr = third.as_ptr();
    let mut labels = vec![first, second, third];

    let selected_0 = select_label(&mut labels, 0).unwrap().as_ptr();
    let selected_1 = select_label(&mut labels, 1).unwrap().as_ptr();
    let selected_2 = select_label(&mut labels, 2).unwrap().as_ptr();

    assert_eq!(selected_0, first_ptr);
    assert_eq!(selected_1, second_ptr);
    assert_eq!(selected_2, third_ptr);
}

#[test]
fn leaves_order_contents_and_allocations_unchanged_after_success() {
    let mut labels = vec![
        String::from("longest"),
        String::from("b"),
        String::from("aa"),
    ];
    let original = labels.clone();
    let original_ptrs: Vec<*const u8> = labels.iter().map(|label| label.as_ptr()).collect();
    let original_caps: Vec<usize> = labels.iter().map(String::capacity).collect();

    assert_eq!(select_label(&mut labels, 0), Some("b"));

    assert_eq!(labels, original);
    assert_eq!(
        labels.iter().map(|label| label.as_ptr()).collect::<Vec<_>>(),
        original_ptrs
    );
    assert_eq!(
        labels.iter().map(String::capacity).collect::<Vec<_>>(),
        original_caps
    );
}

#[test]
fn out_of_range_and_empty_selection_return_none_without_mutation() {
    let mut labels = vec!["bbb".to_string(), "a".to_string(), "cc".to_string()];
    let original = labels.clone();
    let original_ptrs: Vec<*const u8> = labels.iter().map(|label| label.as_ptr()).collect();

    assert_eq!(select_label(&mut labels, labels.len()), None);
    assert_eq!(labels, original);
    assert_eq!(
        labels.iter().map(|label| label.as_ptr()).collect::<Vec<_>>(),
        original_ptrs
    );

    let mut empty: Vec<String> = Vec::new();
    assert_eq!(select_label(&mut empty, 0), None);
}

#[test]
fn supports_empty_strings_as_valid_labels() {
    let mut labels = vec!["x".to_string(), "".to_string(), "aa".to_string()];
    let original = labels.clone();

    assert_eq!(select_label(&mut labels, 0), Some(""));
    assert_eq!(labels, original);
}
