mod solution;

use solution::{consolidate_readings, Reading};

fn reading(sensor: &str, quality: i32, arrival: u32, value: &str) -> Reading {
    Reading {
        sensor: sensor.to_string(),
        quality,
        arrival,
        value: value.to_string(),
    }
}

#[test]
fn consolidates_duplicates_using_all_winner_tiebreakers() {
    let input = vec![
        reading("alpha", 5, 8, "old"),
        reading("alpha", 7, 20, "higher"),
        reading("beta", 9, 12, "late"),
        reading("beta", 9, 3, "early"),
        reading("gamma", 4, 6, "zeta"),
        reading("gamma", 4, 6, "alpha"),
        reading("gamma", 4, 6, "middle"),
    ];

    assert_eq!(
        consolidate_readings(&input),
        vec![
            reading("beta", 9, 3, "early"),
            reading("alpha", 7, 20, "higher"),
            reading("gamma", 4, 6, "alpha"),
        ]
    );
}

#[test]
fn orders_retained_readings_by_every_ranking_key() {
    let input = vec![
        reading("zeta", 10, 2, "a"),
        reading("beta", 10, 1, "z"),
        reading("alpha", 10, 1, "z"),
        reading("delta", 10, 1, "a"),
        reading("gamma", 9, 0, "a"),
    ];

    assert_eq!(
        consolidate_readings(&input),
        vec![
            reading("alpha", 10, 1, "z"),
            reading("beta", 10, 1, "z"),
            reading("delta", 10, 1, "a"),
            reading("zeta", 10, 2, "a"),
            reading("gamma", 9, 0, "a"),
        ]
    );
}

#[test]
fn equal_duplicates_still_produce_exactly_one_reading() {
    let input = vec![
        reading("same", 3, 4, "value"),
        reading("same", 3, 4, "value"),
        reading("same", 3, 4, "value"),
    ];

    assert_eq!(
        consolidate_readings(&input),
        vec![reading("same", 3, 4, "value")]
    );
}

#[test]
fn handles_empty_input_and_numeric_boundaries() {
    assert!(consolidate_readings(&[]).is_empty());

    let input = vec![
        reading("minimum", i32::MIN, u32::MAX, "low"),
        reading("maximum", i32::MAX, u32::MAX, "high"),
        reading("maximum", i32::MAX, 0, "preferred"),
    ];

    assert_eq!(
        consolidate_readings(&input),
        vec![
            reading("maximum", i32::MAX, 0, "preferred"),
            reading("minimum", i32::MIN, u32::MAX, "low"),
        ]
    );
}

#[test]
fn does_not_modify_input() {
    let input = vec![
        reading("b", 1, 9, "first"),
        reading("a", 2, 5, "winner"),
        reading("a", 1, 1, "loser"),
    ];
    let original = input.clone();

    let _ = consolidate_readings(&input);

    assert_eq!(input, original);
}
