mod solution;

use solution::{select_finalists, Entry};

fn entry(entrant: &str, score: i64, attempt: u32, division: &str) -> Entry {
    Entry {
        entrant: entrant.to_string(),
        score,
        attempt,
        division: division.to_string(),
    }
}

#[test]
fn selects_one_best_entry_per_entrant_before_applying_limit() {
    let entries = vec![
        entry("ada", 50, 1, "west"),
        entry("bob", 90, 8, "north"),
        entry("ada", 100, 9, "east"),
        entry("cy", 80, 2, "south"),
        entry("ada", 70, 0, "north"),
    ];

    assert_eq!(
        select_finalists(&entries, 2),
        vec![
            entry("ada", 100, 9, "east"),
            entry("bob", 90, 8, "north"),
        ]
    );
}

#[test]
fn resolves_winners_by_attempt_then_division() {
    let entries = vec![
        entry("attempt", 10, 7, "a"),
        entry("attempt", 10, 2, "z"),
        entry("division", 20, 4, "west"),
        entry("division", 20, 4, "east"),
        entry("division", 20, 4, "north"),
    ];

    assert_eq!(
        select_finalists(&entries, usize::MAX),
        vec![
            entry("division", 20, 4, "east"),
            entry("attempt", 10, 2, "z"),
        ]
    );
}

#[test]
fn ranks_finalists_using_all_specified_keys() {
    let entries = vec![
        entry("zara", 30, 3, "a"),
        entry("beth", 30, 1, "z"),
        entry("anna", 30, 1, "west"),
        entry("cara", 30, 1, "east"),
        entry("low", 29, 0, "a"),
    ];

    assert_eq!(
        select_finalists(&entries, 10),
        vec![
            entry("anna", 30, 1, "west"),
            entry("beth", 30, 1, "z"),
            entry("cara", 30, 1, "east"),
            entry("zara", 30, 3, "a"),
            entry("low", 29, 0, "a"),
        ]
    );
}

#[test]
fn duplicate_submissions_do_not_consume_finalist_positions() {
    let entries = vec![
        entry("repeat", 100, 1, "a"),
        entry("repeat", 99, 1, "a"),
        entry("repeat", 98, 1, "a"),
        entry("other", 50, 1, "a"),
    ];

    assert_eq!(
        select_finalists(&entries, 2),
        vec![
            entry("repeat", 100, 1, "a"),
            entry("other", 50, 1, "a"),
        ]
    );
}

#[test]
fn handles_zero_limit_empty_input_and_numeric_boundaries() {
    let entries = vec![
        entry("minimum", i64::MIN, u32::MAX, "z"),
        entry("maximum", i64::MAX, u32::MAX, "a"),
        entry("maximum", i64::MAX, 0, "b"),
    ];

    assert!(select_finalists(&entries, 0).is_empty());
    assert!(select_finalists(&[], 5).is_empty());
    assert_eq!(
        select_finalists(&entries, 10),
        vec![
            entry("maximum", i64::MAX, 0, "b"),
            entry("minimum", i64::MIN, u32::MAX, "z"),
        ]
    );
}

#[test]
fn does_not_modify_input() {
    let entries = vec![
        entry("b", 2, 3, "west"),
        entry("a", 4, 1, "east"),
        entry("a", 3, 0, "north"),
    ];
    let original = entries.clone();

    let _ = select_finalists(&entries, 2);

    assert_eq!(entries, original);
}
"},{"id":"cap-v2-ordering_and_selection-rust-repair-01","test_code":"#[path = "solution.rs"]
mod solution;

use solution::{rank_tasks, Task};

fn task(id: &str, priority: i32, deadline: u32) -> Task {
    Task {
        id: id.to_string(),
        priority,
        deadline,
    }
}

#[test]
fn ranks_by_priority_deadline_and_id() {
    let mut tasks = vec![
        task("zeta", 5, 2),
        task("beta", 7, 9),
        task("omega", 7, 1),
        task("alpha", 7, 1),
        task("low", -2, 0),
    ];

    assert_eq!(
        rank_tasks(&mut tasks),
        vec![
            task("alpha", 7, 1),
            task("omega", 7, 1),
            task("beta", 7, 9),
            task("zeta", 5, 2),
            task("low", -2, 0),
        ]
    );
}

#[test]
fn returns_clones_and_leaves_input_in_original_order_and_content() {
    let mut tasks = vec![
        task("last", 1, 9),
        task("first", 10, 1),
        task("middle", 5, 4),
    ];
    let original = tasks.clone();
    let original_task_addresses: Vec<*const Task> = tasks.iter().map(|item| item as *const Task).collect();
    let original_id_addresses: Vec<*const u8> = tasks.iter().map(|item| item.id.as_ptr()).collect();

    let ranked = rank_tasks(&mut tasks);

    assert_eq!(tasks, original);
    assert_eq!(
        tasks.iter().map(|item| item as *const Task).collect::<Vec<_>>(),
        original_task_addresses
    );
    assert_eq!(
        tasks.iter().map(|item| item.id.as_ptr()).collect::<Vec<_>>(),
        original_id_addresses
    );
    assert_eq!(
        ranked,
        vec![
            task("first", 10, 1),
            task("middle", 5, 4),
            task("last", 1, 9),
        ]
    );
    assert!(ranked.iter().zip(tasks.iter().rev()).all(|(copy, original)| {
        copy.id == original.id && copy.id.as_ptr() != original.id.as_ptr()
    }));
}

#[test]
fn accepts_empty_and_single_element_slices() {
    let mut empty: Vec<Task> = Vec::new();
    assert!(rank_tasks(&mut empty).is_empty());

    let mut one = vec![task("only", 3, 8)];
    let original = one.clone();
    assert_eq!(rank_tasks(&mut one), original);
    assert_eq!(one, original);
}

#[test]
fn handles_numeric_boundaries_without_overflow() {
    let mut tasks = vec![
        task("minimum", i32::MIN, u32::MAX),
        task("maximum-late", i32::MAX, u32::MAX),
        task("maximum-early", i32::MAX, 0),
    ];
    let original = tasks.clone();

    assert_eq!(
        rank_tasks(&mut tasks),
        vec![
            task("maximum-early", i32::MAX, 0),
            task("maximum-late", i32::MAX, u32::MAX),
            task("minimum", i32::MIN, u32::MAX),
        ]
    );
    assert_eq!(tasks, original);
}

#[test]
fn preserves_multiplicity_for_tasks_equal_on_all_keys() {
    let mut tasks = vec![
        task("same", 4, 6),
        task("same", 4, 6),
        task("other", 3, 0),
        task("same", 4, 6),
    ];
    let original = tasks.clone();
    let ranked = rank_tasks(&mut tasks);

    assert_eq!(ranked.len(), 4);
    assert_eq!(ranked[0..3], original[[0, 1, 3]]);
    assert_eq!(ranked[3], original[2]);
    assert_eq!(tasks, original);
}
"},{"id":"cap-v2-ordering_and_selection-rust-repair-02","test_code":"#[path = "solution.rs"]
mod solution;

use solution::select_label;

#[test]
fn selects_by_increasing_byte_length_then_lexicographically() {
    let mut labels = vec![
        "pear".to_string(),
        "a".to_string(),
        "fig".to_string(),
        "kiwi".to_string(),
        "be".to_string(),
        "apple".to_string(),
    ];

    assert_eq!(select_label(&mut labels, 0), Some("a"));
    assert_eq!(select_label(&mut labels, 1), Some("be"));
    assert_eq!(select_label(&mut labels, 2), Some("fig"));
    assert_eq!(select_label(&mut labels, 3), Some("kiwi"));
    assert_eq!(select_label(&mut labels, 4), Some("pear"));
    assert_eq!(select_label(&mut labels, 5), Some("apple"));
}

#[test]
fn uses_utf8_byte_length_rather_than_character_count() {
    let mut labels = vec![
        "é".to_string(),
        "z".to_string(),
        "abc".to_string(),
        "界".to_string(),
    ];

    assert_eq!(select_label(&mut labels, 0), Some("z"));
    assert_eq!(select_label(&mut labels, 1), Some("é"));
    assert_eq!(select_label(&mut labels, 2), Some("abc"));
    assert_eq!(select_label(&mut labels, 3), Some("界"));
}

#[test]
fn identical_labels_tie_by_original_index() {
    let first = String::from("same");
    let second = String::from("same");
    let third = String::from("same");
    let first_ptr = first.as_ptr();
    let second_ptr = second.as_ptr();
    let third_ptr = third.as_ptr();
    let mut labels = vec![first, second, third];

    let selected_0 = select_label(&mut labels, 0).unwrap().as_ptr();
    let selected_1 = select_label(&mut labels, 1).unwrap().as_ptr();
    let selected_2 = select_label(&mut labels, 2).unwrap().as_ptr();

    assert_eq!(selected_0, first_ptr);
    assert_eq!(selected_1, second_ptr);
    assert_eq!(selected_2, third_ptr);
}

#[test]
fn leaves_order_contents_and_allocations_unchanged_after_success() {
    let mut labels = vec![
        String::from("longest"),
        String::from("b"),
        String::from("aa"),
    ];
    let original = labels.clone();
    let original_ptrs: Vec<*const u8> = labels.iter().map(|label| label.as_ptr()).collect();
    let original_caps: Vec<usize> = labels.iter().map(String::capacity).collect();

    assert_eq!(select_label(&mut labels, 0), Some("b"));

    assert_eq!(labels, original);
    assert_eq!(
        labels.iter().map(|label| label.as_ptr()).collect::<Vec<_>>(),
        original_ptrs
    );
    assert_eq!(
        labels.iter().map(String::capacity).collect::<Vec<_>>(),
        original_caps
    );
}

#[test]
fn out_of_range_and_empty_selection_return_none_without_mutation() {
    let mut labels = vec!["bbb".to_string(), "a".to_string(), "cc".to_string()];
    let original = labels.clone();
    let original_ptrs: Vec<*const u8> = labels.iter().map(|label| label.as_ptr()).collect();

    assert_eq!(select_label(&mut labels, labels.len()), None);
    assert_eq!(labels, original);
    assert_eq!(
        labels.iter().map(|label| label.as_ptr()).collect::<Vec<_>>(),
        original_ptrs
    );

    let mut empty: Vec<String> = Vec::new();
    assert_eq!(select_label(&mut empty, 0), None);
}

#[test]
fn supports_empty_strings_as_valid_labels() {
    let mut labels = vec!["x".to_string(), "".to_string(), "aa".to_string()];
    let original = labels.clone();

    assert_eq!(select_label(&mut labels, 0), Some(""));
    assert_eq!(labels, original);
}
"},{"id":"cap-v2-parsing_and_encoding-rust-generation-01","test_code":"#[path = "solution.rs"]
mod solution;

use solution::{parse_manifest, Allocation, ManifestError};

fn allocation(name: &str, units: u32) -> Allocation {
    Allocation {
        name: name.to_string(),
        units,
    }
}

#[test]
fn parses_records_in_order_and_preserves_repeated_names() {
    assert_eq!(
        parse_manifest("alpha=12;beta=0;alpha=7"),
        Ok(vec![
            allocation("alpha", 12),
            allocation("beta", 0),
            allocation("alpha", 7),
        ])
    );
}

#[test]
fn accepts_canonical_units_at_numeric_boundaries() {
    assert_eq!(parse_manifest("zero=0"), Ok(vec![allocation("zero", 0)]));
    assert_eq!(
        parse_manifest("max=4294967295"),
        Ok(vec![allocation("max", u32::MAX)])
    );
}

#[test]
fn reports_empty_overall_input_separately() {
    assert_eq!(parse_manifest(""), Err(ManifestError::EmptyInput));
}

#[test]
fn reports_empty_records_including_trailing_and_leading_separators() {
    assert_eq!(
        parse_manifest("alpha=1;"),
        Err(ManifestError::EmptyRecord { record: 1 })
    );
    assert_eq!(
        parse_manifest(";alpha=1"),
        Err(ManifestError::EmptyRecord { record: 0 })
    );
    assert_eq!(
        parse_manifest("alpha=1;;beta=2"),
        Err(ManifestError::EmptyRecord { record: 1 })
    );
}

#[test]
fn requires_exactly_one_equals_sign_per_record() {
    assert_eq!(
        parse_manifest("alpha1"),
        Err(ManifestError::SeparatorCount { record: 0 })
    );
    assert_eq!(
        parse_manifest("alpha=1=2"),
        Err(ManifestError::SeparatorCount { record: 0 })
    );
    assert_eq!(
        parse_manifest("ok=1;broken;later=2"),
        Err(ManifestError::SeparatorCount { record: 1 })
    );
}

#[test]
fn rejects_empty_non_lowercase_non_ascii_and_whitespace_names() {
    let cases = [
        ("=1", 0),
        ("Alpha=1", 0),
        ("alpha1=1", 0),
        ("a-b=1", 0),
        ("é=1", 0),
        (" alpha=1", 0),
        ("alpha =1", 0),
        ("ok=1;BAD=2", 1),
    ];

    for (input, record) in cases {
        assert_eq!(
            parse_manifest(input),
            Err(ManifestError::InvalidName { record }),
            "unexpected result for {input:?}"
        );
    }
}

#[test]
fn rejects_noncanonical_malformed_and_overflowing_units() {
    let cases = [
        ("a=", 0),
        ("a=00", 0),
        ("a=01", 0),
        ("a=+1", 0),
        ("a=-1", 0),
        ("a=1 ", 0),
        ("a= 1", 0),
        ("a=１２", 0),
        ("a=4294967296", 0),
        ("ok=1;b=02", 1),
    ];

    for (input, record) in cases {
        assert_eq!(
            parse_manifest(input),
            Err(ManifestError::InvalidUnits { record }),
            "unexpected result for {input:?}"
        );
    }
}

#[test]
fn applies_error_precedence_within_a_record() {
    assert_eq!(
        parse_manifest("=="),
        Err(ManifestError::SeparatorCount { record: 0 })
    );
    assert_eq!(
        parse_manifest("BAD=01"),
        Err(ManifestError::InvalidName { record: 0 })
    );
    assert_eq!(
        parse_manifest("=01"),
        Err(ManifestError::InvalidName { record: 0 })
    );
}

#[test]
fn reports_the_first_invalid_record_from_left_to_right() {
    assert_eq!(
        parse_manifest("good=1;BAD=02;also=00"),
        Err(ManifestError::InvalidName { record: 1 })
    );
    assert_eq!(
        parse_manifest("good=1;bad=02;BROKEN"),
        Err(ManifestError::InvalidUnits { record: 1 })
    );
}
