The wire format is:

`WEL1;name#<n>:<value>;id#<n>:<value>;css#<n>:<value>;xpath#<n>:<value>;text#<n>:<value>;`

Each `<n>` is a nonempty unsigned decimal byte length. It counts the UTF-8 bytes in the following value, so values may contain semicolons, colons, `#`, newlines, and non-ASCII characters. Fields must occur exactly in the displayed order. Leading zeroes in a length are accepted.

Return the corresponding error when the prefix or next key is wrong, a length is missing or non-decimal, its arithmetic overflows, its endpoint is outside the input, its endpoint splits a UTF-8 character, a field terminator is missing, or any data remains after the final terminator. In particular, a valid record followed by extra bytes must not be accepted.

Do not include a `main` function, tests, external packages, or filesystem, network, clock, or random operations.","reference_code":"#[derive(Debug, Clone, PartialEq, Eq)]
pub struct WebElement {
    pub name: String,
    pub element_id: String,
    pub css_selector: String,
    pub xpath_selector: String,
    pub text_content: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ParseError {
    BadPrefix,
    ExpectedKey(&'static str),
    InvalidLength,
    LengthOverflow,
    InvalidUtf8Boundary,
    MissingTerminator,
    TrailingData,
}

fn field(input: &str, pos: &mut usize, key: &'static str) -> Result<String, ParseError> {
    let prefix = format!("{}#", key);
    if !input[*pos..].starts_with(&prefix) {
        return Err(ParseError::ExpectedKey(key));
    }
    *pos += prefix.len();

    let rest = &input[*pos..];
    let colon = rest.find(':').ok_or(ParseError::InvalidLength)?;
    let digits = &rest[..colon];
    if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return Err(ParseError::InvalidLength);
    }
    let len = digits.parse::<usize>().map_err(|_| ParseError::LengthOverflow)?;
    *pos += colon + 1;

    let end = (*pos).checked_add(len).ok_or(ParseError::LengthOverflow)?;
    if end > input.len() {
        return Err(ParseError::InvalidLength);
    }
    if !input.is_char_boundary(end) {
        return Err(ParseError::InvalidUtf8Boundary);
    }
    let value = input[*pos..end].to_owned();
    if input.as_bytes().get(end) != Some(&b';') {
        return Err(ParseError::MissingTerminator);
    }
    *pos = end + 1;
    Ok(value)
}

pub fn parse_web_element(input: &str) -> Result<WebElement, ParseError> {
    if !input.starts_with("WEL1;") {
        return Err(ParseError::BadPrefix);
    }
    let mut pos = 5;
    let name = field(input, &mut pos, "name")?;
    let element_id = field(input, &mut pos, "id")?;
    let css_selector = field(input, &mut pos, "css")?;
    let xpath_selector = field(input, &mut pos, "xpath")?;
    let text_content = field(input, &mut pos, "text")?;
    if pos != input.len() {
        return Err(ParseError::TrailingData);
    }
    Ok(WebElement {
        name,
        element_id,
        css_selector,
        xpath_selector,
        text_content,
    })
}
