mod solution;

use solution::{parse_web_element, ParseError, WebElement};

fn field(key: &str, value: &str) -> String {
    format!("{}#{}:{};", key, value.len(), value)
}

fn record(name: &str, id: &str, css: &str, xpath: &str, text: &str) -> String {
    format!(
        "WEL1;{}{}{}{}{}",
        field("name", name),
        field("id", id),
        field("css", css),
        field("xpath", xpath),
        field("text", text)
    )
}

#[test]
fn parses_empty_and_delimiter_rich_values() {
    let input = record("", "a:b;c#d", ".商品\n[x=':;#']", "//a[@id='#x']", "héllo;:\n世界#");
    let expected = WebElement {
        name: String::new(),
        element_id: "a:b;c#d".to_owned(),
        css_selector: ".商品\n[x=':;#']".to_owned(),
        xpath_selector: "//a[@id='#x']".to_owned(),
        text_content: "héllo;:\n世界#".to_owned(),
    };
    assert_eq!(parse_web_element(&input), Ok(expected));
}

#[test]
fn accepts_leading_zero_lengths() {
    let input = "WEL1;name#003:abc;id#000:;css#001:x;xpath#000:;text#002:é;";
    assert_eq!(
        parse_web_element(input),
        Ok(WebElement {
            name: "abc".to_owned(),
            element_id: String::new(),
            css_selector: "x".to_owned(),
            xpath_selector: String::new(),
            text_content: "é".to_owned(),
        })
    );
}

#[test]
fn rejects_bad_prefix_and_wrong_field_order() {
    assert_eq!(
        parse_web_element("WEL2;name#0:;id#0:;css#0:;xpath#0:;text#0:;"),
        Err(ParseError::BadPrefix)
    );
    assert!(matches!(
        parse_web_element("WEL1;id#0:;name#0:;css#0:;xpath#0:;text#0:;"),
        Err(ParseError::ExpectedKey(_))
    ));
    assert!(matches!(
        parse_web_element("WEL1;name#0:;css#0:;id#0:;xpath#0:;text#0:;"),
        Err(ParseError::ExpectedKey(_))
    ));
}

#[test]
fn rejects_missing_and_nond_decimal_lengths() {
    assert_eq!(
        parse_web_element("WEL1;name#:;id#0:;css#0:;xpath#0:;text#0:;"),
        Err(ParseError::InvalidLength)
    );
    assert_eq!(
        parse_web_element("WEL1;name#1x:a;id#0:;css#0:;xpath#0:;text#0:;"),
        Err(ParseError::InvalidLength)
    );
}

#[test]
fn rejects_length_overflow_and_endpoint_past_input() {
    let overflow = format!(
        "WEL1;name#{}:;id#0:;css#0:;xpath#0:;text#0:;",
        "9".repeat(100)
    );
    assert_eq!(parse_web_element(&overflow), Err(ParseError::LengthOverflow));
    assert_eq!(
        parse_web_element("WEL1;name#4:abc"),
        Err(ParseError::InvalidLength)
    );
}

#[test]
fn rejects_utf8_boundary_split() {
    assert_eq!(
        parse_web_element("WEL1;name#1:é;id#0:;css#0:;xpath#0:;text#0:;"),
        Err(ParseError::InvalidUtf8Boundary)
    );
}

#[test]
fn rejects_missing_terminator_and_trailing_data() {
    assert_eq!(
        parse_web_element("WEL1;name#1:aXid#0:;css#0:;xpath#0:;text#0:;"),
        Err(ParseError::MissingTerminator)
    );
    let valid = record("n", "i", "c", "x", "t");
    assert_eq!(
        parse_web_element(&(valid + "extra")),
        Err(ParseError::TrailingData)
    );
}

#[test]
fn parsing_does_not_mutate_owned_input() {
    let input = record("button", "save", "#save", "//button", "Save");
    let before = input.clone();
    assert!(parse_web_element(&input).is_ok());
    assert_eq!(input, before);
}
