mod solution;

use solution::{canonicalize_parameters, QueryError};

#[test]
fn handles_empty_input_and_empty_keys_or_values() {
    assert_eq!(canonicalize_parameters(""), Ok(String::new()));
    assert_eq!(
        canonicalize_parameters("b=&=empty&a=1&="),
        Ok("=empty&=&a=1&b=".to_owned())
    );
}

#[test]
fn sorts_by_decoded_key_and_canonicalizes_escapes() {
    let input = "%7A=%2f&%61=%7e&A=%3d&b=%41";
    assert_eq!(
        canonicalize_parameters(input),
        Ok("A=%3D&a=~&b=A&z=%2F".to_owned())
    );
}

#[test]
fn repeated_keys_retain_original_relative_order() {
    let input = "b=last&a=z&a=a&%61=m&a=0&c=end";
    assert_eq!(
        canonicalize_parameters(input),
        Ok("a=z&a=a&a=m&a=0&b=last&c=end".to_owned())
    );
}

#[test]
fn decodes_utf8_then_reencodes_every_non_unreserved_byte() {
    assert_eq!(
        canonicalize_parameters("%C3%A9=%E4%B8%96%E7%95%8C&plain=-._~AZaz09"),
        Ok("plain=-._~AZaz09&%C3%A9=%E4%B8%96%E7%95%8C".to_owned())
    );
}

#[test]
fn reports_missing_and_extra_equals() {
    assert_eq!(canonicalize_parameters("abc"), Err(QueryError::MissingEquals));
    assert_eq!(canonicalize_parameters("a=b=c"), Err(QueryError::ExtraEquals));
    assert_eq!(canonicalize_parameters("a=1&broken"), Err(QueryError::MissingEquals));
}

#[test]
fn rejects_literal_reserved_and_non_ascii_characters() {
    assert_eq!(canonicalize_parameters("a=hello+world"), Err(QueryError::InvalidCharacter));
    assert_eq!(canonicalize_parameters("é=value"), Err(QueryError::InvalidCharacter));
    assert_eq!(canonicalize_parameters("a=b/c"), Err(QueryError::InvalidCharacter));
}

#[test]
fn rejects_malformed_percent_escapes() {
    assert_eq!(canonicalize_parameters("a=%"), Err(QueryError::InvalidEscape));
    assert_eq!(canonicalize_parameters("a=%0"), Err(QueryError::InvalidEscape));
    assert_eq!(canonicalize_parameters("a=%GG"), Err(QueryError::InvalidEscape));
}

#[test]
fn rejects_decoded_bytes_that_are_not_utf8() {
    assert_eq!(canonicalize_parameters("a=%FF"), Err(QueryError::InvalidUtf8));
    assert_eq!(canonicalize_parameters("%C3%28=x"), Err(QueryError::InvalidUtf8));
}

#[test]
fn accepts_encoded_separator_bytes_as_data() {
    assert_eq!(
        canonicalize_parameters("a=%3D%26%25"),
        Ok("a=%3D%26%25".to_owned())
    );
}

#[test]
fn canonicalization_does_not_mutate_owned_input() {
    let input = String::from("b=2&a=1&a=0");
    let before = input.clone();
    assert_eq!(canonicalize_parameters(&input), Ok("a=1&a=0&b=2".to_owned()));
    assert_eq!(input, before);
}
